script:
var palette = {KIDD:'#28a745', BMSK:'#ffa00a', BBSD:'#b3d4f5', EMFK:'#ee82a6', EFPS:'#5e64ff'};
var fallback = ['#7cd6fd','#743ee2','#ff5858','#ffa00a','#5e64ff','#28a745'];
var chartEl = root_element.querySelector('.rpd-chart');
var legendEl = root_element.querySelector('.rpd-legend');
Promise.all([
  frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Murid', filters:[['status_murid','=','Aktif']], fields:['kode_program'], limit_page_length:0}}),
  frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Program Belajar', fields:['name','program_belajar'], limit_page_length:0}})
]).then(function(res){
  var rows = (res[0].message)||[]; var progs=(res[1].message)||[];
  var nameMap={}; progs.forEach(function(p){ nameMap[p.name]=p.program_belajar||p.name; });
  var counts={}; rows.forEach(function(x){ var k=x.kode_program||'(Tanpa Program)'; counts[k]=(counts[k]||0)+1; });
  var entries=Object.keys(counts).map(function(k){ return {code:k, count:counts[k], name:nameMap[k]||k}; }).sort(function(a,b){ return b.count-a.count; });
  var total=entries.reduce(function(s,e){ return s+e.count; },0);
  if(!total){ chartEl.innerHTML=''; legendEl.innerHTML='<div class="rpd-empty">Belum ada murid aktif.</div>'; return; }
  var size=180, cx=90, cy=90, rO=80, rI=50, ang=-Math.PI/2;
  function polar(rr,a){ return [cx+rr*Math.cos(a), cy+rr*Math.sin(a)]; }
  var segs=[];
  entries.forEach(function(e,i){
    var frac=e.count/total; var a2=ang+frac*2*Math.PI;
    var color=palette[e.code]||fallback[i%fallback.length]; e.color=color; var d;
    if(frac>=0.999){ d='M '+cx+' '+(cy-rO)+' A '+rO+' '+rO+' 0 1 1 '+(cx-0.01)+' '+(cy-rO)+' L '+(cx-0.01)+' '+(cy-rI)+' A '+rI+' '+rI+' 0 1 0 '+cx+' '+(cy-rI)+' Z'; }
    else { var large=(a2-ang)>Math.PI?1:0; var p1=polar(rO,ang),p2=polar(rO,a2),p3=polar(rI,a2),p4=polar(rI,ang); d='M '+p1[0]+' '+p1[1]+' A '+rO+' '+rO+' 0 '+large+' 1 '+p2[0]+' '+p2[1]+' L '+p3[0]+' '+p3[1]+' A '+rI+' '+rI+' 0 '+large+' 0 '+p4[0]+' '+p4[1]+' Z'; }
    segs.push('<path d="'+d+'" fill="'+color+'"><title>'+e.code+' ('+e.name+'): '+e.count+'</title></path>');
    ang=a2;
  });
  chartEl.innerHTML='<svg width="'+size+'" height="'+size+'" viewBox="0 0 '+size+' '+size+'">'+segs.join('')+'</svg>';
  legendEl.innerHTML=entries.map(function(e){ return '<div class="rpd-li"><span class="rpd-sw" style="background:'+e.color+'"></span><span class="rpd-code">'+e.code+'</span><span class="rpd-name">'+frappe.utils.escape_html(e.name)+'</span><span class="rpd-cnt">'+e.count+'</span></div>'; }).join('');
});

var THRESH=4, DAYS=30, ABSEN='Alpa';
var listEl=root_element.querySelector('.rpa-list');
listEl.innerHTML='<div class="rpa-loading">Memuat…</div>';
var since=frappe.datetime.add_days(frappe.datetime.get_today(), -DAYS);
frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Sesi Kelas', filters:[['tanggal_sesi','>=',since],['status_sesi','=','Terlaksana']], fields:['name','kelas'], limit_page_length:0}}).then(function(sres){
  var sesi=sres.message||[];
  if(!sesi.length){ listEl.innerHTML='<div class="rpa-empty">Belum ada sesi terlaksana dalam '+DAYS+' hari terakhir.</div>'; return; }
  var kelasOf={}, names=[];
  sesi.forEach(function(s){ kelasOf[s.name]=s.kelas; names.push(s.name); });
  return frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Presensi Murid', filters:[['parenttype','=','Rumba Sesi Kelas'],['parent','in',names],['status_kehadiran','=',ABSEN]], fields:['murid','nama_murid','parent'], limit_page_length:0}}).then(function(pres){
    var rows=pres.message||[]; var agg={};
    rows.forEach(function(r){ var k=r.murid||r.nama_murid; if(!agg[k]) agg[k]={murid:r.murid, nama:r.nama_murid, kelas:kelasOf[r.parent]||'', n:0}; agg[k].n++; });
    var over=Object.keys(agg).map(function(k){return agg[k];}).filter(function(x){return x.n>THRESH;});
    if(!over.length){ listEl.innerHTML='<div class="rpa-empty">Tidak ada murid dengan Alpa lebih dari '+THRESH+'× dalam '+DAYS+' hari terakhir.</div>'; return; }
    var ids=over.map(function(x){return x.murid;}).filter(Boolean);
    return frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Murid', filters:[['name','in',ids],['status_murid','=','Aktif']], fields:['name'], limit_page_length:0}}).then(function(mres){
      var act={}; (mres.message||[]).forEach(function(m){ act[m.name]=1; });
      var fin=over.filter(function(x){ return !x.murid || act[x.murid]; }).sort(function(a,b){return b.n-a.n;});
      if(!fin.length){ listEl.innerHTML='<div class="rpa-empty">Tidak ada murid aktif dengan Alpa lebih dari '+THRESH+'× dalam '+DAYS+' hari terakhir.</div>'; return; }
      listEl.innerHTML=fin.map(function(x){ var href=x.murid?('/app/rumba-murid/'+encodeURIComponent(x.murid)):'#'; return '<a class="rpa-row" href="'+href+'" style="text-decoration:none"><span class="rpa-name">'+frappe.utils.escape_html(x.nama||x.murid||'-')+'</span><span class="rpa-kelas">'+frappe.utils.escape_html(x.kelas||'')+'</span><span class="rpa-count">'+x.n+'× Alpa</span></a>'; }).join('');
    });
  });
}).catch(function(e){ listEl.innerHTML='<div class="rpa-empty">Gagal memuat data.</div>'; });

(async () => {
  const body = root_element.querySelector('.sl-body');
  const SUMBER = [
    ['instagram','Instagram'],['facebook','Facebook'],['website_bimbelrumba','Website RUMBA'],
    ['pencarian_di_internet','Pencarian internet'],['kawan','Kawan'],['keluarga','Keluarga'],
    ['sekolah','Sekolah'],['kegiatan_rumba','Kegiatan RUMBA'],['spanduk_di_jalan','Spanduk di jalan'],
    ['brosur_selebaran','Brosur / selebaran'],['lainnya','Lainnya']
  ];
  try {
    const res = await frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Lead', fields:SUMBER.map(s=>s[0]), limit_page_length:0}});
    const rows = res.message || [];
    if (!rows.length) { body.innerHTML = '<div class="sl-empty">Belum ada data lead.</div>'; return; }
    const counts = SUMBER.map(([f,label]) => [label, rows.reduce((n,r)=>n+(r[f]?1:0),0)]).sort((a,b)=>b[1]-a[1]);
    const max = Math.max(1, ...counts.map(c=>c[1]));
    const esc = frappe.utils.escape_html;
    body.innerHTML = counts.map(([label,n]) => '<div class="sl-row"><div class="sl-label">'+esc(label)+'</div><div class="sl-bar-wrap"><div class="sl-bar" style="width:'+Math.round(n/max*100)+'%"></div></div><div class="sl-count">'+n+'</div></div>').join('')
      + '<div class="sl-empty" style="padding-top:8px;font-size:11px">Total lead: '+rows.length+' · satu lead bisa memilih lebih dari satu sumber</div>';
  } catch(e) { body.innerHTML = '<div class="sl-empty">Gagal memuat data sumber.</div>'; console.error(e); }
})();

(async () => {
  const body = root_element.querySelector('.ss-body');
  try {
    const today = frappe.datetime.get_today();
    let emp = null;
    try {
      const ev = await frappe.db.get_value('Employee', {user_id: frappe.session.user}, 'name');
      emp = ev && ev.message && ev.message.name;
    } catch(permErr) { emp = null; }
    if (!emp) { body.innerHTML = '<div class="ss-empty">Akun Anda belum tertaut ke data Employee. Hubungi Admin Unit.</div>'; return; }
    const res = await frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Sesi Kelas', filters:{tanggal_sesi: today}, or_filters:[['guru','=',emp],['guru_pengganti','=',emp]], fields:['name','kelas','jam_sesi','status_sesi','workflow_state','nama_unit'], order_by:'jam_sesi asc', limit_page_length:0}});
    const rows = res.message || [];
    if (!rows.length) { body.innerHTML = '<div class="ss-empty">Tidak ada sesi Anda hari ini.</div>'; return; }
    const kelasIds = [...new Set(rows.map(r=>r.kelas).filter(Boolean))];
    let kelasMap = {};
    if (kelasIds.length) {
      const kr = await frappe.call({method:'frappe.client.get_list', args:{doctype:'Rumba Kelas', filters:{name:['in',kelasIds]}, fields:['name','nama_kelas'], limit_page_length:0}});
      (kr.message||[]).forEach(k=>kelasMap[k.name]=k.nama_kelas);
    }
    const esc = frappe.utils.escape_html;
    body.innerHTML = rows.map(r => '<div class="ss-row" data-name="'+esc(r.name)+'"><div class="ss-main"><div class="ss-kelas">'+esc(kelasMap[r.kelas]||r.kelas||'')+'</div><div class="ss-meta">'+esc(r.jam_sesi||'-')+' · '+esc(r.nama_unit||'')+' · '+esc(r.workflow_state||r.status_sesi||'')+'</div></div><div class="ss-cta">Isi Presensi ›</div></div>').join('');
    body.querySelectorAll('.ss-row').forEach(el => el.addEventListener('click', () => frappe.set_route('Form','Rumba Sesi Kelas', el.dataset.name)));
  } catch(e) { body.innerHTML = '<div class="ss-empty">Gagal memuat sesi.</div>'; console.error(e); }
})();
